// Stock profile defaults (FUN_4948): 0 = default, 1 = Fn/Ctrl swapped, 2 = Mac, 3 = Mac + Fn/Ctrl swapped.
void profile_switch_user(uint8_t profile) {
    if (profile == 1 || profile == 3) {
        layer_on(_FNCTL);
    } else {
        layer_off(_FNCTL);
    }
    if (profile == 2 || profile == 3) {
        layer_on(_MAC);
    } else {
        layer_off(_MAC);
    }
}
